# -*- coding: utf-8 -*-
"""Generate tests/fixtures/flaw_corpus/vector/tiling_pattern_self_referential.pdf

GitHub #53. The corpus already carries `vector/tiling_pattern_large_steps.pdf`,
which stresses the tiler with an enormous XStep/YStep on a wide page. It does
NOT cover the other hostile tiling shape #53 names: a tiling pattern whose own
content stream paints ITSELF.

The recursion is set up entirely through legal PDF structure, so a parser has
no syntactic reason to reject it:

    page  /Resources /Pattern /P1 -> 5 0 R      page paints a /P1-filled rect
    5 0 R /Resources /Pattern /P1 -> 5 0 R      the pattern paints a /P1-filled
                                                 rect -- i.e. itself

Each nesting level is a valid tile, so a painter that does not impose its own
recursion limit descends forever. The flaw class is unbounded recursion (and
the stack exhaustion or wall-clock blowup that follows) in the pattern painter,
reachable from a 700-byte file with no compression, no encryption and no
malformed syntax to trip an earlier check.

Deterministic: no randomness, no timestamps, fixed /ID. Re-running must produce
byte-identical output, which `--check` verifies against the committed file.

Usage:
    python tests/fixtures/gen_tiling_pattern_self_referential.py
    python tests/fixtures/gen_tiling_pattern_self_referential.py --check

No third-party dependencies (house style: see gen_identity_stmf.py,
gen_decompression_bomb.py).
"""

from __future__ import annotations

import argparse
import pathlib
import sys

# Pinned so the output is byte-reproducible.
DOC_ID = "5331545F53454C465245465F5449"

PAGE_W = 200
PAGE_H = 200

# The page paints one rectangle filled with pattern /P1.
PAGE_CONTENT = b"q /Pattern cs /P1 scn 0 0 200 200 re f Q\n"

# The pattern's OWN content stream paints a rectangle filled with /P1 -- the
# same pattern object. This is the self-reference.
PATTERN_CONTENT = b"q /Pattern cs /P1 scn 0 0 50 50 re f Q\n"


def build_pdf() -> bytes:
    objects: list[bytes] = []

    # 1: catalog
    objects.append(b"<< /Type /Catalog /Pages 2 0 R >>")

    # 2: page tree
    objects.append(b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>")

    # 3: the page. Its /Pattern resource is object 5.
    objects.append(
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %d %d] "
        b"/Resources << /Pattern << /P1 5 0 R >> >> "
        b"/Contents 4 0 R >>" % (PAGE_W, PAGE_H)
    )

    # 4: page content stream
    objects.append(
        b"<< /Length %d >>\nstream\n%s\nendstream" % (len(PAGE_CONTENT), PAGE_CONTENT)
    )

    # 5: the self-referential tiling pattern. /Resources /Pattern /P1 is 5 0 R,
    #    i.e. this very object, and the stream paints with /P1.
    objects.append(
        b"<< /Type /Pattern /PatternType 1 /PaintType 1 /TilingType 1 "
        b"/BBox [0 0 50 50] /XStep 50 /YStep 50 "
        b"/Resources << /Pattern << /P1 5 0 R >> >> "
        b"/Length %d >>\nstream\n%s\nendstream" % (len(PATTERN_CONTENT), PATTERN_CONTENT)
    )

    out = bytearray()
    out += b"%PDF-1.4\n"
    # A binary comment line marks the file as binary for transfer-mode sniffers.
    out += b"%\xe2\xe3\xcf\xd3\n"

    offsets = [0] * (len(objects) + 1)
    for i, body in enumerate(objects, start=1):
        offsets[i] = len(out)
        out += b"%d 0 obj\n" % i
        out += body
        out += b"\nendobj\n"

    xref_at = len(out)
    n = len(objects) + 1
    out += b"xref\n0 %d\n" % n
    out += b"0000000000 65535 f \n"
    for i in range(1, n):
        out += b"%010d 00000 n \n" % offsets[i]

    out += b"trailer\n"
    out += b"<< /Size %d /Root 1 0 R /ID [<%s> <%s>] >>\n" % (
        n,
        DOC_ID.encode("ascii"),
        DOC_ID.encode("ascii"),
    )
    out += b"startxref\n%d\n" % xref_at
    out += b"%%EOF\n"
    return bytes(out)


def target_path() -> pathlib.Path:
    return (
        pathlib.Path(__file__).resolve().parent
        / "flaw_corpus"
        / "vector"
        / "tiling_pattern_self_referential.pdf"
    )


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "--check",
        action="store_true",
        help="verify the committed file matches freshly generated bytes",
    )
    args = ap.parse_args()

    data = build_pdf()
    target = target_path()

    if args.check:
        if not target.exists():
            print("MISSING: %s" % target)
            return 1
        on_disk = target.read_bytes()
        if on_disk != data:
            print(
                "MISMATCH: %s is %d bytes, regenerated is %d bytes"
                % (target, len(on_disk), len(data))
            )
            return 1
        print("ok: %s matches freshly generated bytes (%d bytes)" % (target, len(data)))
        return 0

    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)
    print("wrote %s (%d bytes)" % (target, len(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
